    <div class="row"><div class="col-md-6"><div class="form-group"><label>Repositório ativo</label><input class="form-control" value="<?= ctr_e($data['Repository']['CasRpsDsc'] ?? ''); ?>" readonly><input type="hidden" name="RepositoryId" value="<?= ctr_e($data['Repository']['CasRpsCod'] ?? ''); ?>"></div></div><div class="col-md-6"><div class="form-group"><label for="PackageHash">Hash do pacote</label><input class="form-control font-monospace" id="PackageHash" name="PackageHash" maxlength="64" value="<?= ctr_e($data['FormData']['PackageHash'] ?? ''); ?>" required></div></div></div>
